export function bindControls(root,sim,camera){const q=s=>root.querySelector(s);const holds=new Map();let sequence=0;let storage;try{storage=window.localStorage;}catch{}const bestScores=createBestScores(storage);
 q('#spawn').replaceChildren(...Object.entries(SPAWNS).map(([key,p])=>{const o=document.createElement('option');o.value=key;o.textContent=p.label;if(key==='f')o.selected=true;return o;}));
 q('#boat-select').replaceChildren(...Object.values(FLEET).filter(entry=>!entry.npcOnly).map(entry=>{const o=document.createElement('option');o.value=entry.id;o.textContent=entry.name;return o;}));
 const windDial=bindDirectionDial(root,'wind'),currentDial=bindDirectionDial(root,'current');
 const buttons=[...root.querySelectorAll('.engine-button[data-engine]')];
 function applyHolds(){for(const side of ['port','stbd']){const active=[...holds.values()].filter(h=>h.engine===side||h.engine==='both').sort((a,b)=>b.order-a.order)[0];sim.state[side]=!sim.failures?.[side]&&active?active.power:0;}if(['singleOutboard','singleInboardRudder'].includes(sim.boat.propulsion.type))sim.state.stbd=0;const thruster=[...holds.values()].filter(h=>h.engine==='thruster').sort((a,b)=>b.order-a.order)[0];sim.state.bowThruster=!sim.failures?.bowThruster&&sim.boat.propulsion.bowThruster&&thruster?thruster.power:0;recordControlStates(sim);for(const button of buttons){const held=[...holds.values()].some(h=>h.button===button);button.classList.toggle('held',held);button.setAttribute('aria-pressed',String(held));}update();}
 function begin(token,button){if(button.disabled)return;if(button.dataset.engine!=='thruster')registerRaceThrottle(sim);holds.set(token,{button,engine:button.dataset.engine,power:+button.dataset.power/100,order:++sequence});applyHolds();}
 function end(token){if(holds.delete(token))applyHolds();}
 const neutral=()=>{centerSteering();holds.clear();applyHolds();};
 for(const button of buttons){button.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();button.setPointerCapture(e.pointerId);begin('pointer:'+e.pointerId,button);});for(const name of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(name,e=>end('pointer:'+e.pointerId));button.addEventListener('keydown',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(!e.repeat)begin('key:'+button.dataset.engine+button.dataset.power,button);}});button.addEventListener('keyup',e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();end('key:'+button.dataset.engine+button.dataset.power);}});button.addEventListener('blur',()=>end('key:'+button.dataset.engine+button.dataset.power));button.addEventListener('contextmenu',e=>e.preventDefault());}
 for(const name of ['pointerup','pointercancel'])window.addEventListener(name,e=>end('pointer:'+e.pointerId));
 function update(){const failures=sim.failures||{},message=failureText(failures),noticeBox=q('#failure-notice');noticeBox.hidden=!message;noticeBox.textContent=message;for(const button of buttons){const engine=button.dataset.engine;button.disabled=!!failures[engine]||(engine==='thruster'&&!!failures.bowThruster)||(engine==='both'&&!!(failures.port||failures.stbd));}const locked=!!camera.lockedPose,lockButton=q('#camera-lock');lockButton.textContent=locked?'Unlock view':'Lock view';lockButton.setAttribute('aria-pressed',String(locked));lockButton.setAttribute('aria-label',locked?'Unlock the camera and resume following the boat':'Lock this camera position and viewing angle to the map');const notice=contactNotice(sim),feedback=q('#contact-feedback');feedback.hidden=!notice;if(notice){feedback.dataset.severity=notice.severity;q('#contact-label').textContent=notice.label;q('#contact-detail').textContent=notice.knots.toFixed(2)+' kt toward '+(notice.kind==='boat'?'boat':'dock')+(notice.protected?' · fenders deployed':'')+(sim.mode==='levels'&&!sim.levelRun?.score&&sim.levelRun?.definition.contactPenalties!==false?' · +'+notice.seconds+'s':'');}updateLevelUI();const anchor=sim.anchor;q('#anchor-status').textContent=anchor.notice||({stowed:'Stowed',deployed:'Paying out',holding:'Holding rode',retrieving:'Retrieving'}[anchor.mode]+(anchor.target?' · '+anchor.lengthFt.toFixed(1)+' ft · '+(anchor.tension>.002?'Taut':'Slack'):''));for(const [id,mode] of [['down','deployed'],['hold','holding'],['up','retrieving']]){q('#anchor-'+id).setAttribute('aria-pressed',String(anchor.mode===mode));q('#anchor-'+id).disabled=id!=='down'&&anchor.mode==='stowed';}q('#other-boats-note').textContent=(sim.otherBoats?.length||0)+' parked boats · starting area kept clear';const s=sim.state;for(const [key,id] of [['port','pv'],['stbd','sv']])q('#'+id).textContent=s[key]===0?'N':(s[key]>0?'Ahead ':'Reverse ')+Math.round(Math.abs(s[key])*100)+'%';q('#bv').textContent=s.port===s.stbd?(s.port===0?'N':(s.port>0?'Ahead ':'Reverse ')+Math.round(Math.abs(s.port)*100)+'%'):'Mixed';q('#av').textContent=s.steer+'°';q('#av-scene').textContent=s.steer+'°';q('#steer-scene').value=s.steer;q('#steer').value=s.steer;for(const side of ['port','stbd'])q('#overlay-'+side).textContent=s[side]===0?'N':(s[side]>0?'FWD ':'REV ')+Math.round(Math.abs(s[side])*100)+'%';q('#overlay-both').textContent=q('#bv').textContent;q('#moving-traffic-note').textContent=(sim.trafficDensity==='high'?10:sim.trafficDensity==='medium'?5:0)+' traffic boats · hold course underway; wait about 50 ft off occupied destinations';q('#helm-height').value=camera.helmHeightOffset??0;q('#helm-height-value').textContent='+'+(camera.helmHeightOffset??0).toFixed(2)+' ft';q('#helm-height-note').textContent='Helm eye height: '+((sim.helm?.height??6.262)+(camera.helmHeightOffset??0)).toFixed(1)+' ft above water. Applies in Helm view.';q('#cv').textContent=(camera.catchup??3)+' s';q('#view').textContent='View · '+({far:'Far',medium:'Medium',helm:'Helm'}[camera.mode]);q('#catchup-note').textContent=camera.mode==='helm'?'Helm stays aligned with the boat':'Far / Medium follow delay · 0 = immediate';q('#wv').textContent=sim.environment.wind+' kt';q('#uv').textContent=sim.environment.current.toFixed(1)+' kt';const degrees=sim.environment.windDirection,directions=['N','NE','E','SE','S','SW','W','NW'];q('#dv').textContent=directions[Math.round(degrees/45)%8]+' · '+degrees+'°';q('#ud').textContent=directions[Math.round(sim.environment.currentDirection/45)%8]+' · '+sim.environment.currentDirection+'°';windDial.update();currentDial.update();q('.scene-hint').textContent=camera.lockedPose?'View locked to map · unlock to move camera':performance.now()<(camera.lockNoticeUntil||0)?'Boat left view · camera follow resumed':camera.mode==='helm'?'Drag to look · Recenter to face forward':'Drag to look · release to return';q('#wind-arrow').textContent='Wind → '+directions[Math.round(degrees/45)%8]+' · waves travel downwind';q('#readout').textContent=(Math.hypot(s.vx,s.vy)*110).toFixed(1)+' kt';
 for(const side of ['port','stbd'])for(const type of Object.keys(LINE_DEFS)){const line=sim.lines[lineKey(type,side)],button=q('#line-'+side+'-'+type),status=line?(line.tension>.0005?'Taut':'Slack'):'Released';button.setAttribute('aria-pressed',String(!!line));button.dataset.state=status.toLowerCase();button.querySelector('small').textContent=status;}
 for(const side of ['port','stbd']){const b=q('#fender-'+side);b.setAttribute('aria-pressed',String(sim.fenders[side]));b.querySelector('small').textContent=sim.fenders[side]?'Deployed':'Stowed';}
 }
 function sync(){sim.state.steer=+q('#steer').value;if(sim.mode!=='levels'){sim.environment.wind=+q('#wind').value;sim.environment.windDirection=+q('#wind-direction').value;sim.environment.current=+q('#current').value;sim.environment.currentDirection=+q('#current-direction').value;}update();}
 for(const key of ['wind','wind-direction','current','current-direction'])q('#'+key).oninput=sync;
 q('#anchor-down').onclick=()=>{anchorDown(sim);update();};q('#anchor-hold').onclick=()=>{anchorHold(sim);update();};q('#anchor-up').onclick=()=>{anchorUp(sim);update();};
 q('#setup-open').onclick=()=>{if(sim.mode==='levels')return;neutral();q('#setup-screen').showModal();};q('#setup-close').onclick=()=>{sim.sessionActive=true;q('#setup-screen').close();};q('#setup-screen').addEventListener('cancel',e=>e.preventDefault());
 const centerSteering=bindMomentarySteering([q('#steer'),q('#steer-scene')],value=>{sim.state.steer=value;update();},()=>sim.model.id==='deadrise-40');
 const orientation=matchMedia('(orientation: landscape)');let landscape=orientation.matches;const checkOrientation=()=>{if(orientation.matches!==landscape){landscape=orientation.matches;neutral();}};orientation.addEventListener('change',checkOrientation);const anchorTools=q('.anchor-tools');function placeAnchorControls(){q(orientation.matches?'#anchor-landscape':'#anchor-portrait').append(anchorTools);}orientation.addEventListener('change',placeAnchorControls);placeAnchorControls();window.addEventListener('resize',checkOrientation);window.addEventListener('orientationchange',neutral);
 q('#camera-lock').onclick=()=>{if(camera.lockedPose)unlockCamera(camera);else lockCamera(camera,sim.state,sim.scale,sim.helm);update();};
 q('#helm-height').oninput=()=>{unlockCamera(camera);camera.helmHeightOffset=+q('#helm-height').value;update();};
 q('#catchup').oninput=()=>{camera.catchup=+q('#catchup').value;update();};
 q('#view').onclick=()=>{const modes=['far','medium','helm'];camera.mode=modes[(modes.indexOf(camera.mode)+1)%3];resetCamera(camera,sim.state,sim.scale);update();};
 q('#recenter').onclick=()=>{resetCamera(camera,sim.state,sim.scale);update();};
 q('#map-toggle').onclick=()=>{const b=q('#map-toggle'),expanded=b.classList.toggle('expanded');b.setAttribute('aria-expanded',String(expanded));};
 for(const b of root.querySelectorAll('[data-steer]'))b.onclick=()=>{q('#steer').value=b.dataset.steer;sync();};
 function reset(){if(sim.mode==='levels'&&sim.levelRun){launchLevel(sim.levelRun.definition.id);return;}neutral();sim.contactFeedback=null;resetSimulation(sim,q('#spawn').value);resetCamera(camera,sim.state,sim.scale);q('#steer').value=0;update();}
 function updateBoatControls(){q('header strong').textContent='Docking Trainer · '+sim.model.definition.name;const workboat=sim.model.id==='deadrise-40';for(const id of ['steer','steer-scene'])q('#'+id).setAttribute('aria-label',workboat?'Steering angle, hold to steer, release to centre':'Steering angle, stays set until adjusted or centred');const single=workboat||sim.boat.propulsion.type==='singleOutboard';for(const button of buttons){if(button.dataset.engine==='thruster')continue;const original=Number(button.dataset.originalPower??button.dataset.power);button.dataset.originalPower=original;const power=workboat?Math.sign(original)*(Math.abs(original)===25?100:50):original;button.dataset.power=power;button.textContent=Math.abs(power)+(power>0?' FWD':' REV');}for(const column of root.querySelectorAll('.engine-column')){const engine=column.querySelector('[data-engine]')?.dataset.engine;column.style.display=single&&engine!=='port'?'none':'';}q('.engine-controls').style.gridTemplateColumns=single?'1fr':'';q('.scene-throttle.stbd').style.display=single?'none':'';q('.scene-throttle.both').style.display=single?'none':'';q('.engine-column .column-title').firstChild.nodeValue=single?'ENGINE ':'PORT ';q('.scene-throttle.port strong').firstChild.nodeValue=single?'ENGINE':'PORT';for(const button of root.querySelectorAll('[data-engine=port]'))button.setAttribute('aria-label',(single?'Engine':'Port engine')+' '+Math.abs(+button.dataset.power)+' percent '+(+button.dataset.power>0?'ahead':'reverse')+', hold for power');for(const el of root.querySelectorAll('[data-thruster-controls]'))el.hidden=!sim.boat.propulsion.bowThruster;q('#boat-note').textContent=workboat?'40-foot deadrise · fixed shaft and rudder · 50% / 100% power · planing hull':single?'21-foot bowrider · one steerable outboard':sim.model.id==='Express-33'?'33.5 feet overall · existing twin-sterndrive handling':sim.model.id==='sportfisher-30'?'30-foot hull · old 30-foot twin-inboard handling':'60-foot motor yacht · twin inboards · bow thruster';}

 function syncSetup(){q('#boat-select').value=sim.model.id;q('#spawn').value=sim.spawnId;q('#other-boats').value=sim.otherBoatsDensity;q('#moving-traffic').value=sim.trafficDensity||'none';for(const [id,key] of [['wind','wind'],['current','current'],['wind-direction','windDirection'],['current-direction','currentDirection']])q('#'+id).value=sim.environment[key];q('#steer').value=0;updateBoatControls();}
 function closeMenus(){for(const id of ['setup-screen','settings-screen','home-screen','level-result'])if(q('#'+id).open)q('#'+id).close();}
 function launchLevel(id){neutral();closeMenus();sim.contactFeedback=null;startLevel(sim,id);sim.sessionActive=true;syncSetup();resetCamera(camera,sim.state,sim.scale);update();}
 function endSession(){sim.sessionActive=false;neutral();enterPractice(sim);resetSimulation(sim,sim.spawnId);sim.contactFeedback=null;closeMenus();syncSetup();resetCamera(camera,sim.state,sim.scale);}
 function goHome(view='modes'){endSession();homeView(view);q('#home-screen').showModal();update();}
 function practice(){neutral();q('#home-screen').close();syncSetup();q('#setup-screen').showModal();update();}
 function positionResult(){const helm=q('.helm-panel').getBoundingClientRect(),portrait=!orientation.matches;const room=Math.max(180,window.innerHeight-helm.top);q('#level-result').style.setProperty('--result-height',room+'px');if(portrait){q('#level-result').style.top=Math.max(0,helm.top)+'px';q('#level-result').style.bottom='auto';}else{q('#level-result').style.top='';q('#level-result').style.bottom='';}}
 window.addEventListener('resize',()=>{if(q('#level-result').open)positionResult();});
 function updateLevelUI(){const run=sim.levelRun,active=sim.mode==='levels'&&!!run;q('#setup-open').hidden=active;q('#settings-open').hidden=!active;q('#levels-open').hidden=!active;q('#reset').textContent=active?'Restart level':'Reset boat';
 for(const id of ['boat-select','spawn','other-boats','moving-traffic','wind','current'])q('#'+id).disabled=active;for(const id of ['wind-compass','current-compass']){q('#'+id).setAttribute('aria-disabled',String(active));q('#'+id).tabIndex=active?-1:0;}
 const light=q('#race-start-light'),colour=raceLight(run);light.hidden=!active||!colour;light.dataset.colour=colour||'';light.querySelector('span').textContent=colour==='green'?'GO':colour==='yellow'?'READY':'WAIT';light.setAttribute('aria-label',colour?colour+' starting light':'Starting lights off');q('#levels-open').textContent=run?.definition.type==='race'?'Races':'Challenges';const collection=run?.definition.type==='race'?RACES:LEVELS;q('#reset').textContent=active?(run.definition.type==='race'?'Restart race':'Restart challenge'):'Reset boat';q('#level-restart').textContent=run?.definition.type==='race'?'Restart race':'Restart challenge';q('#level-next').textContent=run?.definition.type==='race'?'Next course':'Next challenge';q('#result-levels').textContent=run?.definition.type==='race'?'Races':'Challenges';const hud=q('#level-hud');hud.hidden=!active;if(!active)return;const timedOnly=run.definition.contactPenalties===false,last=run.impacts[run.impacts.length-1],feedback=last&&run.elapsed-last.at<3?' · '+last.severity+(timedOnly?'':' +'+last.seconds+'s'):'';const breakdown=run.score?scoreBreakdown(sim):null;hud.textContent=(run.definition.type==='race'?'Course ':'Challenge ')+run.definition.number+' · '+formatTime(run.elapsed)+(breakdown?' · Safety '+breakdown.safety+' · Efficiency '+breakdown.efficiency:' + '+run.penalty+'s'+feedback)+'\n'+(run.complete?'Complete':run.status||run.definition.objective);
 if(run.complete&&!run.resultShown){run.resultShown=true;neutral();const saved=bestScores.save(run);q('#level-result-best').textContent=saved.best?((saved.saved?'New local best · ':'Local best · ')+(run.result?saved.best.total+' / 100':formatTime(saved.best.total))+(saved.persistent?'':' · Session only: browser storage unavailable')):'';q('#level-result-title').textContent=run.definition.name+' complete';q('#level-result-summary').textContent=run.result?'Score '+run.result.total+' / 100 · Time '+formatTime(run.elapsed):'Time '+formatTime(run.elapsed)+' + penalties '+run.penalty+'s = '+formatTime(run.total);const detail=q('#level-result-breakdown');detail.hidden=!run.result;detail.replaceChildren();if(run.result){for(const text of ['Safety '+run.result.safety+' / 100 (70% weight)','Final control '+run.result.finalControl+' / 100 (20% weight)','Efficiency '+run.result.efficiency+' / 100 (10% weight)',run.result.shifts+' gear changes · '+run.result.reversals+' direction reversals',...run.result.feedback]){const p=document.createElement('p');p.textContent=text;detail.append(p);}}const counts=Object.fromEntries(['gentle','firm','hard','crash'].map(k=>[k,run.impacts.filter(i=>i.severity===k).length]));q('#level-result-contacts').textContent='Contacts: '+Object.entries(counts).map(([k,n])=>k+' '+n).join(' · ');q('#level-next').hidden=run.definition.number===collection.length;positionResult();q('#level-result').showModal();}
 }
 q('#level-restart').onclick=()=>launchLevel(sim.levelRun.definition.id);q('#level-next').onclick=()=>launchLevel((sim.levelRun.definition.type==='race'?RACES:LEVELS)[sim.levelRun.definition.number].id);q('#level-result').addEventListener('cancel',e=>e.preventDefault());
 function homeView(view='modes'){for(const node of root.querySelectorAll('[data-best-id]')){const l=[...LEVELS,...RACES].find(l=>l.id===node.dataset.bestId),record=bestScores.get(l);node.textContent=record?'Local best: '+(l.type==='race'?formatTime(record.total):record.total+' / 100'):'No local score yet';}for(const [id,name]of [['home-modes','modes'],['home-level-panel','levels'],['home-race-panel','races'],['home-instruction-panel','instructions']])q('#'+id).hidden=view!==name;}
 q('#home-open').onclick=()=>goHome();q('#setup-home').onclick=()=>goHome();q('#result-home').onclick=()=>goHome();
 q('#home-practice').onclick=practice;
 q('#home-levels').onclick=()=>homeView('levels');q('#home-races').onclick=()=>homeView('races');q('#races-home').onclick=()=>homeView();q('#levels-open').onclick=()=>goHome(sim.levelRun?.definition.type==='race'?'races':'levels');q('#result-levels').onclick=()=>goHome(sim.levelRun?.definition.type==='race'?'races':'levels');
 q('#home-instructions').onclick=()=>homeView('instructions');q('#levels-home').onclick=()=>homeView();q('#instructions-home').onclick=()=>homeView();q('#home-screen').addEventListener('cancel',e=>e.preventDefault());
 function openSettings(){neutral();q('#settings-close').textContent=sim.sessionActive?'Back to game':'Home';q('#settings-screen').showModal();}
 q('#home-settings').onclick=openSettings;q('#settings-open').onclick=openSettings;q('#settings-close').onclick=()=>q('#settings-screen').close();
 for(const [list,definitions] of [['home-level-list',LEVELS],['home-race-list',RACES]])q('#'+list).replaceChildren(...definitions.flatMap(l=>{const b=document.createElement('button');b.type='button';b.className='btn home-level-card';const title=document.createElement('strong'),detail=document.createElement('span');title.textContent=l.number+' · '+l.name;detail.textContent='Group '+(l.group||1)+' · '+FLEET[l.boat].name+' · Wind '+(l.wind||0)+' kt · Current '+(l.current||0)+' kt · '+l.objective+(l.failures?' · '+failureText(l.failures):'');const record=bestScores.get(l),best=document.createElement('span');best.className='local-best';best.dataset.bestId=l.id;best.textContent=record?'Local best: '+(l.type==='race'?formatTime(record.total):record.total+' / 100'):'No local score yet';b.append(title,detail,best);b.onclick=()=>launchLevel(l.id);if(l.type!=='race'&&l.taskNumber===1){const heading=document.createElement('h3');heading.className='challenge-group-heading';heading.textContent=['','Group 1 · Foundations (1–10)','Group 2 · Weather (11–20)','Group 3 · Advanced (21–30)'][l.group];return [heading,b];}return [b];}));
 q('#other-boats').value=sim.otherBoatsDensity||'none';
 q('#moving-traffic').onchange=()=>{neutral();setPracticeTraffic(sim,q('#moving-traffic').value);update();};
 q('#other-boats').onchange=()=>{const density=q('#other-boats').value;neutral();setOtherBoats(sim,density);update();};
 q('#boat-select').onchange=()=>{neutral();sim.contactFeedback=null;selectBoat(sim,q('#boat-select').value,q('#spawn').value);resetCamera(camera,sim.state,sim.scale);q('#steer').value=0;updateBoatControls();update();};updateBoatControls();
 q('#reset').onclick=reset;q('#spawn').onchange=reset;
 for(const side of ['port','stbd'])for(const type of Object.keys(LINE_DEFS))q('#line-'+side+'-'+type).onclick=()=>{recordLineRelease(sim,sim.lines[lineKey(type,side)]);const notice=attachLine(sim,type,side);const button=q('#line-'+side+'-'+type);button.title=notice;update();};
 for(const side of ['port','stbd'])q('#fender-'+side).onclick=()=>{sim.fenders[side]=!sim.fenders[side];update();};
 // Switching tabs always puts both engines into neutral.

 window.addEventListener('blur',neutral);document.addEventListener('visibilitychange',()=>{if(document.hidden)neutral();});
 sim.sessionActive=false;update();q('#home-screen').showModal();return {update,reset};
}


